  cpEmailOffer: { th: "ต้องการให้ส่งลิงก์ส่วนตัวไปที่อีเมลที่คุณให้ไว้ไหม", en: "Would you like the private link sent to the email address you gave?" },
  cpEmailButton: { th: "ส่งลิงก์ทางอีเมล", en: "Email me the link" },
