  cpReopenReasonHint: { th: "ไม่บังคับ ไม่เกิน 1,000 ตัวอักษร ข้อความเข้ารหัสไว้", en: "Optional. Up to 1,000 characters. It is encrypted" },
  cpReopenYes: { th: "เปิดเรื่องอีกครั้ง", en: "Reopen my complaint" },
