  perfNotEnough: { th: "ข้อมูลไม่พอ", en: "Not enough data" },
  perfUnavailable: { th: "ขณะนี้ยังแสดงตัวเลขไม่ได้ ลองใหม่ภายหลัง", en: "We cannot show the figures right now. Try again later" },
