    th: "กองทุน 3 กองทุนช่วยนักศึกษาโดยตรง ได้แก่ กองทุนสำหรับนักศึกษาที่มีความจำเป็นทางการเงิน กองทุนสนับสนุนประกันอุบัติเหตุ และกองทุนการศึกษาระดับบัณฑิตศึกษา ข้อบังคับตั้งกองทุนแต่ไม่ได้บอกวิธียื่นขอ",
